contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 x) public payable {
        uint256 beforeDistributed = c.totalDistributed(); if (__ESBMC_reverted()) return;
        uint256 ownerBal = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        require(x <= ownerBal);

        c.burn(x); if (__ESBMC_reverted()) return;

        uint256 afterDistributed = c.totalDistributed(); if (__ESBMC_reverted()) return;

        assert(afterDistributed == beforeDistributed - x);
    }

    receive() external payable {}
}

